# Hypothesis: a subclass that implements an abstract property with a concrete property is instantiable, while a subclass that omits it is rejected.
from abc import ABC, abstractmethod
from typing import reveal_type


class Shape(ABC):
    @property
    @abstractmethod
    def name(self) -> str:
        raise NotImplementedError

    @abstractmethod
    def area(self) -> float:
        raise NotImplementedError

    def describe(self) -> str:
        return f'{self.name} with area {self.area():.1f}'


class Square(Shape):
    def __init__(self, side: float) -> None:
        self._side = side

    @property
    def name(self) -> str:
        return 'square'

    def area(self) -> float:
        return self._side * self._side


class Blob(Shape):
    def area(self) -> float:
        return 0.0


def make_square() -> Shape:
    return Square(2.0)


def try_blob() -> str:
    try:
        b = Blob()  # expect-error
    except TypeError:
        return 'TypeError'
    return 'built'


sq = Square(3.0)
reveal_type(sq.name)
reveal_type(sq.describe())
print(sq.describe())
shape = make_square()
reveal_type(shape.name)
print(shape.area())
print(try_blob())
